// retry.ts

export interface RetryOptions {
  /** Maximum number of retry attempts after the initial try. */
  retries?: number;
  /** Base delay in milliseconds for the first retry. */
  initialDelayMs?: number;
  /** Multiplier applied to the delay after each attempt. */
  factor?: number;
  /** Upper bound (ms) for any computed delay, applied before jitter. */
  maxDelayMs?: number;
  /** Jitter fraction in [0, 1]. 0 = no jitter, 1 = full jitter. */
  jitter?: number;
  /** Signal that aborts waiting and rejects immediately. */
  signal?: AbortSignal;
  /** Injectable sleeper; defaults to a promise-based setTimeout. */
  sleep?: (ms: number) => Promise<void>;
  /** Injectable random source; defaults to Math.random. */
  random?: () => number;
  /** Decides whether a thrown error should be retried. */
  isRetryable?: (error: unknown) => boolean;
  /** Called before each wait with attempt number and computed delay. */
  onRetry?: (info: { attempt: number; delayMs: number; error: unknown }) => void;
}

